reference_solution:
def count_unique_email_groups(emails):
    groups=set()
    for email in emails:
        local,domain=email.rsplit('@',1)
        local=local.split('+',1)[0].replace('.','').lower()
        groups.add(local+'@'+domain.lower())
    return len(groups)

